  }
);
```

### Centralised error handling (must be after all routes)

```js
// Celebrate (Joi) validation errors are translated automatically:
app.use(errors());

// Generic error handler – never leak stack traces in production
app.use((err, req, res, next) => {
  // Log the error (could be to a file, Sentry, etc.)
  console.error(err);

  const status = err.status || 500;
  const response = {
    error: {
      // In production hide internal messages
      message: process.env.NODE_ENV === 'production'
        ? 'Internal server error'
        : err.message,
      // OPTIONAL: expose validation details if it’s a Celebrate error
      ...(err.isJoi && { details: err.details })
    }
  };
  res.status(status).json(response);
});
```

### Exporting the app (no `listen` here)

```js
module.exports = app;
```

Then create a tiny **server.js** (or `bin/www` if you follow the classic Express generator pattern) that starts the HTTP server **only when the app is run directly**:

```js
// server.js
