// ---------- 6️⃣ Central error handler ----------
app.use((err, req, res, next) => {
  // Log the full error server‑side
  req.log?.error({ err, url: req.originalUrl }, 'Unhandled error');

  const status = err.status || 500;
  const response = {
    error: {
