### Example – Validate a `POST /users` payload with **express‑validator**

```js
const { body, validationResult } = require('express-validator');

app.post(
  '/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name is required and must be ≤100 chars'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required'),
    body('password')
      .isStrongPassword({ minLength: 8 })
      .withMessage('Password must be strong'),
  ],
  asyncWrap(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 Bad Request – send sanitized error details
      return res.status(400).json({ errors: errors.array() });
    }

    const { name, email, password } = req.body;
    // TODO: hash password with bcrypt, store in DB, etc.
    res.status(201).json({ id: 3, name, email });
  })
);
```

*All validator errors are turned into a **400** response; the generic error handler will never expose raw user input.*

