### 4.2 Rate Limiting – mitigate brute‑force / DoS

```js
const rateLimit = require('express-rate-limit');

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  standardHeaders: true,   // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});

app.use('/api/', apiLimiter); // or app.use(apiLimiter) for whole app
```

### 4.3 CORS – explicit whitelist

```js
const cors = require('cors');

const allowedOrigins = [
  'https://my-frontend.example.com',
  // add other trusted origins
];

app.use(cors({
  origin: (origin, callback) => {
    // allow non‑browser requests like health checks (origin may be undefined)
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  credentials: true,
}));
```

