app.get(
  '/users',
  // ---- Validation chain -------------------------------------------------
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be an integer between 1 and 100'),
  ],
  // ---- Controller -------------------------------------------------------
  (req, res, next) => {
    // 1️⃣ Check validation result first
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Pass a proper 400 error to the error handler
      return next(createError(400, { errors: errors.array() }));
    }

    // 2️⃣ Extract validated/clean values
    const page = req.query.page ?? 1;
    const limit = req.query.limit ?? 10;

    // 3️⃣ Simulate data fetch (replace with DB call in real app)
    try {
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        // ... potentially many more rows
      ];

      const start = (page - 1) * limit;
      const paged = allUsers.slice(start, start + limit);

      res.json(paged);
    } catch (err) {
      // Any unexpected error bubbles to the global handler
      next(err);
    }
  },
);

// ---------------------------------------------------
// 4️⃣ 404 handler (must be placed *after* all routes)
// ---------------------------------------------------
app.use((req, res, next) => {
  next(createError(404, 'Resource not found'));
});

// ---------------------------------------------------
// 5️⃣ Centralized error‑handling middleware
// ---------------------------------------------------
app.use((err, req, res, next) => {
  // Log the error (could be replaced with winston/bunyan etc.)
  console.error(err);

  // Determine status code – default to 500 (internal server error)
  const status = err.status || 500;

  // Do **not** leak stack traces to callers in production
  const response = {
    status: 'error',
    message: err.message || 'Internal Server Error',
  };

  // In development, optionally include stack for easier debugging
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
    // If we used http-errors with `errors` payload, include it
    if (err.errors) response.errors = err.errors;
  }

  res.status(status).json(response);
});

// ---------------------------------------------------
// 6️⃣ Server start – use env var with a sensible fallback
// ---------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on http://localhost:${PORT}`);
});

module.exports = app;
