// ---------------------------------------------------------------
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
  // Consider logging + graceful exit
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Attempt graceful shutdown, then exit
  process.exit(1);
});

// ---------------------------------------------------------------
// 11️⃣  Start server (with graceful stop)
// ---------------------------------------------------------------
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received – shutting down gracefully');
  server.close(() => {
    console.log('Closed out remaining connections');
    process.exit(0);
  });
});
```

### Why?

* Guarantees the process does **not** stay alive in a corrupted state.
* Allows container orchestrators (Docker/K8s) to stop the service cleanly.

