// app.js
// Updated with security‑hardening, centralized error handling and input validation scaffolding.

require('dotenv').config();               // Load .env (optional but handy)
const express = require('express');
const helmet = require('helmet');          // Secure HTTP headers
const cors = require('cors');              // Controlled cross‑origin access
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');          // Request logging (avoid console.log in prod)
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ---------- 1️⃣ Global middleware ----------
app.use(helmet());                         // Sets CSP, HSTS, X‑Content‑Type‑Options, etc.
app.disable('x-powered-by');               // Hide Express version

// CORS – adjust the origin list to your actual clients
