app.use(express.json({ limit: '100kb' })); // adjust the limit as needed

// Rate limiting – 100 requests per 15 mins per IP (tune for your traffic)
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
}));

// Logging – in production you may pipe to a log service
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
} else {
  app.use(morgan('combined'));
}

// ---------- 2️⃣ Routes ----------
