  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be between 1 and 100')
  ],
  (req, res, next) => {
    // Centralized validation error handling
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Pass a structured error to the error middleware
      return next({ status: 400, errors: errors.array() });
    }

    // In a real app you'd fetch from DB and possibly paginate using req.query.page/limit
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// ---------- 3️⃣ Central error handler ----------
app.use((err, req, res, next) => {
  // Default to 500 if status not set
  const status = err.status || 500;

  // Log the error (but never leak stack traces in production)
  console.error(`[${new Date().toISOString()}] ${err.stack || err}`);

  const responsePayload = {
    status: 'error',
    message: err.message || 'Internal Server Error',
