  // Include validation errors when they exist
  if (err.errors) {
    responsePayload.validation = err.errors;
  }

  // In development only, expose the stack for debugging
  if (process.env.NODE_ENV !== 'production') {
    responsePayload.stack = err.stack;
  }

  res.status(status).json(responsePayload);
});

// ---------- 4️⃣ Server start ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.info(`🚀 Server running on http://0.0.0.0:${PORT}`);
});

module.exports = app;
```

